const personas = msg.payload.filter(d => d.class === 'person' && d.score > 0.7);

if (personas.length > 0) {
    msg.payload = "SI - " + Math.round(personas[0].score * 100) + "%";
    msg.detectado = true;
} else {
    msg.payload = "NO";
    msg.detectado = false;
}
return msg;

const r = msg.payload;
let dashText;
let telegramMsg = null;

if (!r.persona || r.nombre === "sin_cara") {
    dashText = "sin cara";
} else if (r.nombre === "desconocido") {
    dashText = "desconocido";
} else {
    // persona conocida
    dashText = r.nombre + " (" + r.confianza + "%)";
    flow.set("persona_text", r.nombre);
    flow.set("persona_time", Date.now());
    const ahora = Date.now();
    const COOLDOWN = 60000; // 60s por persona para no spamear
    const last = flow.get("notif_" + r.nombre) || 0;
    if (ahora - last >= COOLDOWN) {
        flow.set("notif_" + r.nombre, ahora);
        const ts = new Date().toLocaleString("es-CL");
        telegramMsg = {
            headers: { "Content-Type": "application/json" },
            payload: {
                chat_id: 0,
                text: "ALERTA SmartHome\nEvento: persona detectada\nPersona: " + r.nombre +
                      " (" + r.confianza + "%)\nHora: " + ts
            }
        };
    }
}

return [telegramMsg, { payload: dashText }];

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) { /* alerta es texto plano */ } }
const t = msg.topic || "";
if (t.endsWith("/temperatura") && p && p.temperatura !== undefined) flow.set("temperatura", p.temperatura);
else if (t.endsWith("/humedad") && p && p.humedad !== undefined) flow.set("humedad", p.humedad);
else if (t.endsWith("/presion") && p && p.presion !== undefined) flow.set("presion", p.presion);
else if (t.endsWith("/sensor_extra") && p && p.sensor_extra !== undefined) flow.set("sensor_extra", p.sensor_extra);
else if (t.endsWith("/alerta")) { flow.set("alerta_text", typeof p === "string" ? p : JSON.stringify(p)); flow.set("alerta_time", Date.now()); }
return null;

const temperatura = flow.get("temperatura");
const humedad = flow.get("humedad");
const presion = flow.get("presion");
const sensor_extra = flow.get("sensor_extra");
// no escribir fila si todavia no llego ningun dato de sensores
if (temperatura === undefined && humedad === undefined && presion === undefined && sensor_extra === undefined) {
    return null;
}
const at = flow.get("alerta_time") || 0;
const alerta = (Date.now() - at < 15000) ? (flow.get("alerta_text") || "normal") : "normal";
const pt = flow.get("persona_time") || 0;
const persona = (Date.now() - pt < 15000) ? (flow.get("persona_text") || "ninguna") : "ninguna";
msg.payload = {
    timestamp: new Date().toISOString(),
    temperatura: temperatura,
    humedad: humedad,
    presion: presion,
    sensor_extra: sensor_extra,
    alerta: alerta,
    persona: persona
};
return msg;

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) {} }
if (!p || p.temperatura === undefined) return null;
msg.payload = p.temperatura;
return msg;

let s = flow.get('estado') || {};
let p = msg.payload;
if (p.temperatura !== undefined) s.temperatura = p.temperatura;
if (p.humedad !== undefined) s.humedad = p.humedad;
if (p.presion !== undefined) s.presion = p.presion;
if (p.sensor_extra !== undefined) s.audio = p.sensor_extra;
flow.set('estado', s);
return null;

let s = flow.get('estado') || {};
if (s.temperatura === undefined) { node.status({fill:'yellow',shape:'ring',text:'sin datos aun'}); return null; }
let ahora = new Date().toLocaleTimeString('es-CL', {hour:'2-digit', minute:'2-digit'});
let prompt = `Eres el sistema de control de una casa inteligente.
Estado actual del hogar:
- Temperatura: ${s.temperatura} C (umbral normal: 30)
- Humedad: ${s.humedad} %
- Presion: ${s.presion} hPa
- Nivel de audio: ${s.audio} (umbral ruido alto: 500)
- Hora local: ${ahora}

Debes ser estricto con los umbrales(si se superan consideralo como alto). Responde SOLAMENTE en español. Analiza el estado y responde SOLO en JSON valido con esta estructura exacta:
{"nivel_alerta":"normal|alto","activar_led":true,"mensaje_alerta":"texto corto","razonamiento":"explicacion breve"}`;
msg.payload = JSON.stringify({ model: 'phi3:mini', prompt: prompt, stream: false, format: 'json' });
msg.headers = { 'Content-Type': 'application/json' };
node.status({fill:'blue',shape:'dot',text:'consultando LLM...'});
return msg;

let r = msg.payload;
let txt = (r && r.response) ? r.response : '';
let d;
try { d = JSON.parse(txt); } catch (e) {
    node.warn('El LLM no devolvio JSON valido: ' + txt);
    node.status({fill:'red', shape:'ring', text:'JSON invalido'});
    return null;
}
let nivel = (d.nivel_alerta || 'normal').toLowerCase();
node.status({fill:'green', shape:'dot', text: nivel});

// Guardar la decision para el semaforo (misma pestaña)
flow.set('llm_nivel', nivel);
flow.set('llm_msg', d.mensaje_alerta || '');

// Salida 1: alerta -> LED + semaforo, ante cualquier nivel distinto de normal (= "alto")
let alerta = null;
if (nivel !== 'normal') {
    alerta = { topic: 'smarthome/equipo01/alerta', payload: d.mensaje_alerta || ('Alerta ' + nivel) };
}
// Salida 2: registro estructurado de la decision
let dec = { topic: 'smarthome/equipo01/llm/decision',
            payload: JSON.stringify({nivel: d.nivel_alerta, mensaje: d.mensaje_alerta, razonamiento: d.razonamiento}) };
// Salida 3: texto del dashboard
let ui = { payload: '[' + (d.nivel_alerta||'?') + '] ' + (d.mensaje_alerta||'') + ' - ' + (d.razonamiento||'') };

return [ alerta ? [alerta] : null, [dec], [ui] ];

const nivel = (flow.get("llm_nivel") || "normal").toLowerCase();
const texto = flow.get("llm_msg") || "";
let estado;
if (nivel === "normal") {
    estado = "🟢 Normal";
} else {
    estado = "🔴 " + (texto || "Alerta");   // "alto" o cualquier nivel distinto de normal
}
msg.payload = estado;
return msg;

let s = flow.get('estado_q') || {};
let p = msg.payload;
if (p.temperatura !== undefined) s.temperatura = p.temperatura;
if (p.humedad !== undefined) s.humedad = p.humedad;
if (p.presion !== undefined) s.presion = p.presion;
if (p.sensor_extra !== undefined) s.audio = p.sensor_extra;
flow.set('estado_q', s);
return null;

let pregunta = (msg.payload && msg.payload.pregunta) ? String(msg.payload.pregunta).trim() : '';
if (!pregunta) { node.status({fill:'yellow',shape:'ring',text:'sin pregunta'}); return null; }
let s = flow.get('estado_q') || {};
let val = (x) => (x === undefined || x === null) ? 's/d' : x;
let prompt = `Eres el asistente de una casa inteligente. Responde en espanol, de forma breve y clara, usando solo los datos entregados.

Estado actual del hogar:
- Temperatura: ${val(s.temperatura)} C
- Humedad: ${val(s.humedad)} %
- Presion: ${val(s.presion)} hPa
- Nivel de audio: ${val(s.audio)} (umbral ruido alto: 500)

Pregunta: ${pregunta}`;
msg.payload = JSON.stringify({ model: 'phi3:mini', prompt: prompt, stream: false });
msg.headers = { 'Content-Type': 'application/json' };
node.status({fill:'blue',shape:'dot',text:'consultando...'});
return msg;

let r = msg.payload;
let texto = (r && r.response) ? String(r.response).trim() : 'Sin respuesta del LLM';
node.status({fill:'green',shape:'dot',text:'ok'});
msg.payload = texto;
msg.topic = 'sh-resp';
return msg;

let g = global.get('gemelo') || {
    estado_actual: { temperatura: null, humedad: null, presion: null, audio: null,
                     persona: false, led: false },
    historial_1h: [],
    alertas_activas: [],
    prediccion_30min: {},
    umbrales: { temperatura: 30, audio: 500 },
    resumen_llm: ''
};
const t = msg.topic || '';
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { /* payload de texto plano (p.ej. alerta) */ }
}

if (t.endsWith('/temperatura') && p && p.temperatura !== undefined) g.estado_actual.temperatura = p.temperatura;
else if (t.endsWith('/humedad') && p && p.humedad !== undefined) g.estado_actual.humedad = p.humedad;
else if (t.endsWith('/presion') && p && p.presion !== undefined) g.estado_actual.presion = p.presion;
else if (t.endsWith('/sensor_extra') && p && p.sensor_extra !== undefined) g.estado_actual.audio = p.sensor_extra;
else if (t.endsWith('/alerta')) {
    const mensaje = (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload);
    // dedupe: el broker entrega el mismo mensaje 2 veces (suscripciones solapadas)
    const ultima = g.alertas_activas[g.alertas_activas.length - 1];
    if (!(ultima && ultima.mensaje === mensaje && Date.now() - new Date(ultima.ts).getTime() < 5000)) {
        g.alertas_activas.push({ ts: new Date().toISOString(), mensaje: mensaje });
    }
} else if (t.endsWith('/camara/evento')) {
    g._persona_ts = Date.now();
} else if (t.endsWith('/control/led')) {
    g.estado_actual.led = (msg.payload === 'on' || msg.payload === true);
} else if (t.indexOf('/prediccion/') !== -1) {
    const variable = t.split('/').pop();
    if (p && p.valor !== undefined) g.prediccion_30min[variable] = p.valor;
}

// vigencia: alertas de los ultimos 10 min, persona vista hace < 60 s
const hace10min = Date.now() - 10 * 60 * 1000;
g.alertas_activas = g.alertas_activas.filter(a => new Date(a.ts).getTime() > hace10min).slice(-20);
g.estado_actual.persona = !!(g._persona_ts && (Date.now() - g._persona_ts) < 60000);
g.ultimo_update = new Date().toISOString();
global.set('gemelo', g);
return null;

// Convierte el mensaje del sensor a line protocol y lo escribe en InfluxDB
const campo = {
    'temperatura': 'temperatura', 'humedad': 'humedad',
    'presion': 'presion', 'sensor_extra': 'audio'
}[(msg.topic || '').split('/').pop()];
if (!campo) return null;
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
const clave = campo === 'audio' ? 'sensor_extra' : campo;
const v = p ? p[clave] : undefined;
if (typeof v !== 'number' || isNaN(v)) return null;

// dedupe: el broker entrega 2 veces el mismo mensaje por suscripciones solapadas
const ultimo = context.get('t_' + campo) || 0;
if (Date.now() - ultimo < 1000) return null;
context.set('t_' + campo, Date.now());

msg.method = 'POST';
msg.url = 'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=ms';
msg.headers = {
    'Authorization': 'Token ' + env.get('INFLUXDB_TOKEN'),
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = 'sensores,equipo=equipo01 ' + campo + '=' + v + ' ' + Date.now();
return msg;

// Reenvia una alerta MQTT al webhook del agente n8n (debounce de 120 s)
if (!(msg.topic || '').endsWith('/alerta')) return null;
const ultimo = context.get('ultimo_fwd') || 0;
if (Date.now() - ultimo < 120000) return null;
context.set('ultimo_fwd', Date.now());
return {
    method: 'POST',
    url: 'http://n8n:5678/webhook/evento-critico',
    headers: { 'Content-Type': 'application/json' },
    payload: { alerta: (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload) }
};

// Cada 1 min: agrega el estado actual al historial (maximo 60 registros = 1 h)
let g = global.get('gemelo');
if (!g || g.estado_actual.temperatura === null) return null;
g.historial_1h.push({
    ts: new Date().toISOString(),
    temperatura: g.estado_actual.temperatura,
    humedad: g.estado_actual.humedad,
    presion: g.estado_actual.presion,
    audio: g.estado_actual.audio
});
if (g.historial_1h.length > 60) g.historial_1h = g.historial_1h.slice(-60);
global.set('gemelo', g);
return null;

const g = global.get('gemelo') || {};
const salida = {
    ultimo_update: g.ultimo_update || null,
    estado_actual: g.estado_actual || {},
    historial_1h: g.historial_1h || [],
    alertas_activas: (g.alertas_activas || []).map(a => a.mensaje),
    prediccion_30min: g.prediccion_30min || {},
    umbrales: g.umbrales || {},
    resumen_llm: g.resumen_llm || ''
};
msg.payload = salida;
msg.statusCode = 200;
return msg;

// Ejecuta una accion del agente: llega { herramienta, parametros, razonamiento? }
// Salidas: [ mqtt out, escritura InfluxDB (eventos), respuesta HTTP ]
const b = msg.payload || {};
const h = b.herramienta;
const p = b.parametros || {};
let g = global.get('gemelo') || {};
const lp = (texto) => String(texto).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

let mqttMsg = null, influxMsg = null;
let detalle = '';

if (h === 'activar_actuador') {
    const disp = p.dispositivo || 'led';
    const estado = (p.estado === true || p.estado === 'true' || p.estado === 'on');
    // semantica del LED del proyecto: control/led espera "on"/"off"
    mqttMsg = { topic: 'smarthome/equipo01/control/' + disp, payload: estado ? 'on' : 'off' };
    detalle = 'actuador ' + disp + ' -> ' + (estado ? 'on' : 'off');
} else if (h === 'enviar_notificacion') {
    mqttMsg = { topic: 'smarthome/equipo01/llm/notificacion', payload: String(p.mensaje || '') };
    detalle = 'notificacion: ' + (p.mensaje || '');
} else if (h === 'registrar_evento') {
    detalle = 'evento: ' + (p.descripcion || '');
} else if (h === 'ajustar_umbral') {
    g.umbrales = g.umbrales || {};
    if (p.sensor && p.nuevo_umbral !== undefined) {
        g.umbrales[p.sensor] = Number(p.nuevo_umbral);
        global.set('gemelo', g);
    }
    detalle = 'umbral ' + p.sensor + ' -> ' + p.nuevo_umbral;
} else {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'herramienta desconocida: ' + h };
    return [null, null, msg];
}

// registro del uso de la herramienta en InfluxDB (measurement eventos)
influxMsg = {
    method: 'POST',
    url: 'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=ms',
    headers: { 'Authorization': 'Token ' + env.get('INFLUXDB_TOKEN'),
               'Content-Type': 'text/plain; charset=utf-8' },
    payload: 'eventos,origen=agente herramienta="' + lp(h) + '",detalle="' + lp(detalle) + '" ' + Date.now()
};

msg.statusCode = 200;
msg.payload = { ok: true, ejecutado: h, detalle: detalle };
return [mqttMsg, influxMsg, msg];

// Registra el ciclo de razonamiento del agente.
// Llega { razonamiento, acciones: [...] }
// Salidas: [ mqtt llm/decision, escritura InfluxDB (agente), respuesta HTTP ]
const b = msg.payload || {};
const razonamiento = String(b.razonamiento || '');
const acciones = Array.isArray(b.acciones) ? b.acciones : [];
const lp = (texto) => String(texto).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

let g = global.get('gemelo') || {};
g.resumen_llm = razonamiento;
global.set('gemelo', g);

const mqttMsg = {
    topic: 'smarthome/equipo01/llm/decision',
    payload: JSON.stringify({ razonamiento: razonamiento, acciones: acciones })
};
const resumenAcc = acciones.map(a => a.herramienta || '?').join(',') || 'ninguna';
const influxMsg = {
    method: 'POST',
    url: 'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=ms',
    headers: { 'Authorization': 'Token ' + env.get('INFLUXDB_TOKEN'),
               'Content-Type': 'text/plain; charset=utf-8' },
    payload: 'agente,origen=n8n razonamiento="' + lp(razonamiento) + '",acciones="' + lp(resumenAcc)
             + '",n_acciones=' + acciones.length + 'i ' + Date.now()
};

msg.statusCode = 200;
msg.payload = { ok: true };
return [mqttMsg, influxMsg, msg];

// Webhook de la alerta de Grafana -> publica alerta MQTT
// Salidas: [ mqtt alerta, respuesta HTTP ]
const b = msg.payload || {};
const titulo = b.title || (b.alerts && b.alerts[0] && b.alerts[0].labels && b.alerts[0].labels.alertname) || 'Alerta Grafana';
const mqttMsg = {
    topic: 'smarthome/equipo01/alerta',
    payload: JSON.stringify({ tipo: 'grafana', mensaje: titulo })
};
msg.statusCode = 200;
msg.payload = { ok: true };
return [mqttMsg, msg];
